import { MeshStandardNodeMaterial } from 'three/webgpu';
import { mix, color, uv } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, BoxGeometry, Vector3 } = ctx.THREE;

  // Helper to create a slab mesh with gradient material
  function createSlab(width, height, depth, params) {
    const geometry = new BoxGeometry(width, height, depth);
    const mat = new MeshStandardNodeMaterial();
    // Diagonal gradient (approximate with uv.x)
    const grad = mix(color('#101017'), color('#1a1a22'), uv().x);
    mat.color = grad;
    mat.metalness = 0.45;
    mat.roughness = 0.5;
    mat.clearcoat = 0.2;
    mat.transparent = true;
    mat.opacity = 0;
    const mesh = new Mesh(geometry, mat);
    // Store disposables
    mat.userData = { _geometry: geometry, _material: mat };
    return mesh;
  }

  // Helper to create emissive tick bar
  function createTick(width, height, depth) {
    const geometry = new BoxGeometry(width, height, depth);
    const mat = new MeshStandardNodeMaterial();
    mat.emissive = color('#ff2a38');
    mat.emissiveIntensity = 1.3;
    mat.metalness = 0.0;
    mat.roughness = 0.5;
    mat.transparent = true;
    mat.opacity = 0;
    const mesh = new Mesh(geometry, mat);
    mat.userData = { _geometry: geometry, _material: mat };
    return mesh;
  }

  // Grid dimensions
  const GRID_WIDTH = 5.5;
  const GRID_HEIGHT = 3.5;
  const GUTTER = 0.25;
  const PAD = 0.5;
  const SLAB_DEPTH = 0.06;
  const CHAMFER = 0.04; // visual only, not modeled

  const group = new Group();

  // Header caption
  const header = ctx.fontAtlas.createText('ATELIER METRICS / Q2 2026', {
    fontSize: 18,
    color: '#ff2a38',
    align: 'left',
    letterSpacing: 0.12,
  });
  header.position.set(-GRID_WIDTH / 2, GRID_HEIGHT / 2 + 0.5, 0);
  group.add(header);

  // Cell definitions
  const cells = [];

  // Dominant cell (left column)
  cells.push({
    name: 'dominant',
    width: 3.25,
    height: 3.5,
    value: { text: '0.002 mm', role: 'valueLarge', fontSize: 124 },
    label: { text: 'Case tolerance, CNC pass', role: 'label', fontSize: 18 },
    position: new Vector3(- (GRID_WIDTH / 2) + 3.25 / 2, 0, 0),
  });

  // Top secondary cell
  cells.push({
    name: 'secondaryTop',
    width: 2.0,
    height: 1.625,
    value: { text: '38 h', role: 'value', fontSize: 68 },
    label: { text: 'Power reserve, NA-01', role: 'label', fontSize: 18 },
    position: new Vector3(
      (GRID_WIDTH / 2) - 2.0 / 2,
      (GRID_HEIGHT / 2) - 1.625 / 2,
      0
    ),
  });

  // Bottom secondary cell
  cells.push({
    name: 'secondaryBottom',
    width: 2.0,
    height: 1.625,
    value: { text: '214', role: 'value', fontSize: 68 },
    label: { text: 'Components per calibre', role: 'label', fontSize: 18 },
    position: new Vector3(
      (GRID_WIDTH / 2) - 2.0 / 2,
      -(GRID_HEIGHT / 2) + 1.625 / 2,
      0
    ),
  });

  const timelines = [];

  cells.forEach((cellInfo, idx) => {
    const cellGroup = new Group();
    cellGroup.position.copy(cellInfo.position);
    // Create slab
    const slab = createSlab(cellInfo.width, cellInfo.height, SLAB_DEPTH);
    cellGroup.add(slab);

    // Tick bar
    const tick = createTick(0.4, 0.05, SLAB_DEPTH);
    // Position tick inside padding, top‑left
    const tickX = -cellInfo.width / 2 + PAD + 0.4 / 2;
    const tickY = cellInfo.height / 2 - PAD - 0.05 / 2;
    tick.position.set(tickX, tickY, SLAB_DEPTH / 2 + 0.001);
    cellGroup.add(tick);

    // Text values
    const txtValue = ctx.fontAtlas.createText(cellInfo.value.text, {
      fontSize: cellInfo.value.fontSize,
      color: '#e8ecf2',
      align: 'left',
    });

    const txtLabel = ctx.fontAtlas.createText(cellInfo.label.text, {
      fontSize: cellInfo.label.fontSize,
      color: '#e8ecf2',
      align: 'left',
    });

    // Position texts inside padding, stacked vertically
    const txtStartY = cellInfo.height / 2 - PAD - cellInfo.value.fontSize * 0.01; // approximate conversion
    txtValue.position.set(-cellInfo.width / 2 + PAD, txtStartY, SLAB_DEPTH / 2 + 0.002);
    txtLabel.position.set(-cellInfo.width / 2 + PAD, txtStartY - cellInfo.value.fontSize * 0.01 - 0.15, SLAB_DEPTH / 2 + 0.002);
    cellGroup.add(txtValue);
    cellGroup.add(txtLabel);

    // Ensure all materials are transparent for fade‑in
    [slab, tick].forEach((m) => {
      if (m.material) {
        m.material.transparent = true;
        m.material.opacity = 0;
      }
    });
    [txtValue, txtLabel].forEach((obj) => {
      obj.traverse((c) => {
        if (c.isMesh && c.material) {
          c.material.transparent = true;
          c.material.opacity = 0;
        }
      });
    });

    // Hover interaction
    const hoverTimeline = gsap.timeline({ paused: true });
    cellGroup.userData.handlers = {
      pointerover: () => {
        hoverTimeline.clear();
        hoverTimeline.to(
          cellGroup.scale,
          { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'cubic-bezier(0.175,0.885,0.32,1.275)' },
          0
        );
      },
      pointerout: () => {
        hoverTimeline.clear();
        hoverTimeline.to(
          cellGroup.scale,
          { x: 1, y: 1, z: 1, duration: 0.9, ease: 'cubic-bezier(0.165,0.84,0.44,1)' },
          0
        );
      },
    };

    group.add(cellGroup);
    cells[idx].group = cellGroup;
  });

  // Entrance animation (stagger‑cards, fade‑up)
  const entranceTL = gsap.timeline();
  cells.forEach((c, i) => {
    const target = c.group;
    // Store original Y for return animation
    const originalY = target.position.y;
    target.position.y += 0.2;
    target.traverse((obj) => {
      if (obj.isMesh && obj.material) {
        obj.material.opacity = 0;
      }
    });

    entranceTL.to(
      target.position,
      { y: originalY, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
      i * 0.08
    );
    entranceTL.to(
      target.children.map((ch) => ch.material).filter(Boolean),
      { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
      i * 0.08
    );
  });

  timelines.push(entranceTL);

  // Cleanup
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    // Dispose geometries and materials
    group.traverse((obj) => {
      if (obj.isMesh) {
        const mat = obj.material;
        const geo = obj.geometry;
        if (mat) {
          if (mat.map) mat.map.dispose();
          mat.dispose();
        }
        if (geo) geo.dispose();
      }
    });
  };

  return group;
}
